package com.example

import androidx.compose.material3.*
import androidx.compose.runtime.Composable

@Composable
fun SettingsScreen(onSave: () -> Unit) {
    Column {
        TopAppBar(title = { Text("Einstellungen") })
        Text("Allgemeine Einstellungen")
        OutlinedTextField(
            value = "",
            onValueChange = {},
            label = { Text("E-Mail-Adresse") },
            placeholder = { Text("max.mustermann@example.de") }
        )
        Button(onClick = onSave) {
            Text("Speichern")
        }
        Icon(
            imageVector = Icons.Default.Settings,
            contentDescription = "Einstellungen oeffnen"
        )
    }
}

package com.example

import androidx.compose.material3.*
import androidx.compose.runtime.Composable

@Composable
fun JournalScreen(entryCount: Int, userName: String) {
    Column {
        Text("Hallo $userName!")
        val countText = if (entryCount == 1) "1 Eintrag" else "$entryCount Eintraege"
        Text(countText)
        Text("Heute hast du %d neue Erinnerungen.")
        Snackbar { Text("Speichern fehlgeschlagen: $userName") }
    }
}

